      typography: { body: 'Helvetica', headings: 'Helvetica', headingScale: 100, bodySize: 16 },
      // pageLayout grew: gridColumns matches the real "网格列数" stepper (default 4),
      // containerPadding matches the inner container side padding (px).
      pageLayout: { width: 1200, sectionSpacing: 40, gridColumns: 4, containerPadding: 24 },
