  // Render the storefront header logo — img if logo.image is set (sized by
  // logo.width), else fallback text. Used in storefront preview header,
  // password page, etc. Per-section logoText overrides take precedence over
  // the global theme-settings logoText fallback.
  function storeLogoMarkup(sectionLogoText) {
    const settings = state.themeSettings || {};
    const image = settings.logo?.image;
    const width = Math.max(40, Math.min(400, Number(settings.logo?.width) || 160));
    const text = sectionLogoText || settings.logoText || state.storeName || '';
    if (image) {
      return `<img class="store-logo-image" src="${escapeAttr(image)}" alt="${escapeAttr(text)}" style="max-width:${width}px;" />`;
    }
    return escapeHtml(text);
  }

  function ensureThemeSettings(target = state) {
    const defaults = defaultThemeSettings();
    target.themeSettings = target.themeSettings || {};
    target.themeSettings.colorSchemes = Array.isArray(target.themeSettings.colorSchemes) ? target.themeSettings.colorSchemes : clone(defaults.colorSchemes);
    for (const scheme of defaults.colorSchemes) {
      if (!target.themeSettings.colorSchemes.some((candidate) => candidate.id === scheme.id)) {
        target.themeSettings.colorSchemes.push(clone(scheme));
      }
    }
    // Backfill new per-scheme color slots on schemes saved before the 2026-06-02
    // expansion (background → button*/accent etc). Defaults derived from existing
    // bg/text/accent so the migration is value-preserving on every legacy doc.
    for (const scheme of target.themeSettings.colorSchemes) {
      if (scheme.backgroundGradient === undefined) scheme.backgroundGradient = null;
      if (!scheme.buttonSolidBg) scheme.buttonSolidBg = scheme.accent || scheme.text || '#005bd3';
      if (!scheme.buttonSolidLabel) scheme.buttonSolidLabel = scheme.background || '#ffffff';
      if (!scheme.buttonOutline) scheme.buttonOutline = scheme.accent || scheme.text || '#005bd3';
    }
    target.themeSettings.selectedScheme = target.themeSettings.selectedScheme || defaults.selectedScheme;
    for (const [key, value] of Object.entries(defaults)) {
      if (key === 'colorSchemes' || key === 'selectedScheme') continue;
      if (target.themeSettings[key] === undefined) target.themeSettings[key] = clone(value);
      else if (value && typeof value === 'object' && !Array.isArray(value)) {
        if (!target.themeSettings[key] || typeof target.themeSettings[key] !== 'object') {
          const previous = target.themeSettings[key];
          target.themeSettings[key] = clone(value);
          if (key === 'typography' && previous) {
            target.themeSettings[key].body = previous;
            target.themeSettings[key].headings = previous;
          }
        } else {
          target.themeSettings[key] = { ...clone(value), ...target.themeSettings[key] };
        }
      }
    }
    return target.themeSettings;
  }

  function ensureAppEmbeds(target = state) {
    const defaults = defaultAppEmbeds();
    target.appEmbeds = target.appEmbeds || {};
    target.appEmbeds.search = target.appEmbeds.search || '';
    if (!Array.isArray(target.appEmbeds.recommendations)) target.appEmbeds.recommendations = [];
    const blockOnlyAppIds = new Set(APP_SECTIONS.filter((option) => option.surface === 'block').map((option) => option.appId));
    target.appEmbeds.recommendations = target.appEmbeds.recommendations.filter((app) => !blockOnlyAppIds.has(app.id));
    for (const app of defaults.recommendations) {
      const existing = target.appEmbeds.recommendations.find((candidate) => candidate.id === app.id);
      if (!existing) {
        target.appEmbeds.recommendations.push(clone(app));
        continue;
      }
      Object.assign(existing, { ...clone(app), ...existing });
      existing.enabled = Boolean(existing.enabled);
      existing.installed = Boolean(existing.installed);
    }
    return target.appEmbeds;
  }

  function ensureThemeAppBlocks(target = state) {
    if (!Array.isArray(target.themeAppBlocks)) target.themeAppBlocks = [];
    for (const block of defaultThemeAppBlocks()) {
      const existing = target.themeAppBlocks.find((candidate) => candidate.id === block.id);
      if (!existing) {
        target.themeAppBlocks.push(clone(block));
        continue;
      }
      Object.assign(existing, { ...clone(block), ...existing });
      existing.enabled = Boolean(existing.enabled);
      existing.installed = Boolean(existing.installed);
    }
    return target.themeAppBlocks;
  }

  function ensureThemeAssets(target = state) {
    if (!Array.isArray(target.themeFiles)) target.themeFiles = clone(defaultThemeFiles());
    for (const file of defaultThemeFiles()) {
      const existing = target.themeFiles.find((candidate) => candidate.path === file.path);
      if (!existing) target.themeFiles.push(clone(file));
      else Object.assign(existing, { ...clone(file), ...existing });
    }
    if (!Array.isArray(target.themeDefaultContent)) target.themeDefaultContent = clone(defaultThemeContent());
    for (const item of defaultThemeContent()) {
      const existing = target.themeDefaultContent.find((candidate) => candidate.id === item.id);
      if (!existing) target.themeDefaultContent.push(clone(item));
      else Object.assign(existing, { ...clone(item), ...existing });
    }
    target.themeDownloads = Array.isArray(target.themeDownloads) ? target.themeDownloads : [];
    return target;
  }

