      <p class="settings-note">该模板由“创建元对象模板”生成，公开 /metaobjects/${escapeHtml(definition.handle)}/${escapeHtml(section.settings.entryHandle || entries[0]?.handle || 'default')} 会复用这里保存的模板。</p>
